CREATE DATABASE IF NOT EXISTS elegance CHARACTER SET utf8mb4; USE elegance;
CREATE TABLE users(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(120),email VARCHAR(160) UNIQUE,phone VARCHAR(30),password_hash VARCHAR(255),role ENUM('customer','admin') DEFAULT 'customer',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE products(id INT AUTO_INCREMENT PRIMARY KEY,name VARCHAR(160),category VARCHAR(60),description TEXT,price INT NOT NULL,fabric VARCHAR(80),lead_time VARCHAR(80),image VARCHAR(255),status ENUM('draft','published','archived') DEFAULT 'published');
CREATE TABLE measurement_profiles(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,name VARCHAR(80),unit ENUM('cm','in') DEFAULT 'cm',data JSON,needs_review TINYINT DEFAULT 0,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE custom_requests(id INT AUTO_INCREMENT PRIMARY KEY,user_id INT NOT NULL,category VARCHAR(60),description TEXT,fabric VARCHAR(120),event_date DATE NULL,budget VARCHAR(60),contact_pref VARCHAR(20),status ENUM('submitted','quoted','accepted','declined') DEFAULT 'submitted',quote_amount INT NULL,created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE orders(id INT AUTO_INCREMENT PRIMARY KEY,ref VARCHAR(24) UNIQUE,user_id INT NOT NULL,product_id INT NULL,item_name VARCHAR(160),size VARCHAR(40),measurement_snapshot JSON NULL,total INT NOT NULL,channel ENUM('paystack','whatsapp','custom'),payment_status ENUM('awaiting','paid','failed','refunded') DEFAULT 'awaiting',status ENUM('pending_review','awaiting_quotation','awaiting_payment','confirmed','in_production','quality_check','ready','dispatched','delivered','cancelled') DEFAULT 'pending_review',created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,FOREIGN KEY(user_id) REFERENCES users(id));
CREATE TABLE payments(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT,reference VARCHAR(40) UNIQUE,amount INT,status VARCHAR(20),paid_at DATETIME NULL,FOREIGN KEY(order_id) REFERENCES orders(id));
CREATE TABLE order_status_history(id INT AUTO_INCREMENT PRIMARY KEY,order_id INT,actor_id INT NULL,note VARCHAR(160),created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP);
